                ["`BACKUP_RESTORE_KEEP_PRIOR`", "`24h`", "How long the database a restore replaced is kept"],
                ["`BACKUP_UPLOAD_CHUNK_SIZE`", "16 MiB", "Size of upload pieces (1 to 64 MiB); above 32 MiB raise `FRONTEND_API_BODY_LIMIT` too"],
